WITH with_windows AS (SELECT id, store_id, product_id, last_restock, MIN(quantity) OVER w_grp AS running_min_quantity, SUM(quantity) OVER w_grp AS running_sum_quantity, COUNT(quantity) OVER w_grp AS running_count_quantity, SUM(quantity) OVER w_recent AS running_quantity FROM inventory WINDOW w_grp AS (PARTITION BY product_id, store_id ORDER BY quantity, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), w_recent AS (PARTITION BY product_id ORDER BY last_restock, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), with_dims AS (SELECT a.id, a.store_id, a.product_id, a.running_sum_quantity, d.launch_date, d.price, d.cost FROM with_windows a LEFT JOIN products d ON a.product_id = d.id), enriched AS (SELECT *, LAST_VALUE(cost) IGNORE NULLS OVER (PARTITION BY product_id ORDER BY cost, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_cost, AVG(cost) OVER (PARTITION BY store_id ORDER BY launch_date, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS cost_avg_2_prior FROM with_dims), enriched_inventory AS (SELECT *, DENSE_RANK() OVER (PARTITION BY store_id ORDER BY cost_avg_2_prior DESC NULLS LAST) AS cost_avg_2_prior_dense_rank, SUM(cost_avg_2_prior) OVER (PARTITION BY store_id ORDER BY cost_avg_2_prior, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_cost_avg_2_prior FROM enriched WHERE price >= 350), with_dims_inventory AS (SELECT s.*, b.region FROM enriched_inventory s LEFT JOIN stores b ON s.store_id = b.id), metrics AS (SELECT *, STDDEV_SAMP(cost_avg_2_prior_dense_rank) OVER w_running AS product_id_stddev_samp_cost_avg_2_prior_dense_rank, SUM(price) OVER (ORDER BY running_cost_avg_2_prior, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_price FROM with_dims_inventory WINDOW w_running AS (PARTITION BY product_id)), remaining_keys AS (SELECT product_id, id FROM metrics EXCEPT ALL SELECT product_id, id FROM inventory WHERE MONTH(last_restock) IN (2, 3, 6)), kept_rows AS (SELECT s.* FROM metrics s JOIN remaining_keys k ON s.product_id = k.product_id AND s.id = k.id) SELECT id, store_id, product_id, running_sum_quantity, launch_date, cost, last_known_cost, cost_avg_2_prior_dense_rank, running_cost_avg_2_prior, region, product_id_stddev_samp_cost_avg_2_prior_dense_rank, running_price, CUME_DIST() OVER (ORDER BY product_id_stddev_samp_cost_avg_2_prior_dense_rank NULLS FIRST) AS product_id_stddev_samp_cost_avg_2_prior_dense_rank_cume_dist, ROUND(cost_avg_2_prior_dense_rank / SUM(cost_avg_2_prior_dense_rank) OVER (PARTITION BY store_id, region), 4) AS cost_avg_2_prior_dense_rank_share, PERCENT_RANK() OVER (ORDER BY cost_avg_2_prior DESC NULLS LAST) AS cost_avg_2_prior_percent_rank FROM kept_rows
